                data.character_slots.forEach((lover, index) => {
                    const tab = document.createElement('div');
                    tab.className = 'char-tab';
                    tab.textContent = lover.name || `角色 ${index + 1}`;
                    tab.dataset.index = index;
                    tab.addEventListener('click', (e) => {
                        if (e.currentTarget.classList.contains('active')) return;
                        renderLoverInfo(lover);
                        document.querySelectorAll('.char-tab').forEach(t => t.classList.remove('active'));
                        e.currentTarget.classList.add('active');
                    });
                    charSelector.appendChild(tab);
                });

                const activeIndex = (data.active_slot || 1) - 1;
                if (data.character_slots[activeIndex]) {
                    renderLoverInfo(data.character_slots[activeIndex]);
                    const activeTab = charSelector.querySelector(`[data-index='${activeIndex}']`);
                    if (activeTab) activeTab.classList.add('active');
                }

            } catch (e) {
                console.error("状态栏JSON解析错误:", e);
                const container = document.querySelector('.status-container');
                if(container) container.innerHTML = `<p style="color:#ff7b7b; text-align:center;">[状态栏数据错误] 无法加载恋人信息。</p>`;
            }
        });
    </script>
</body>
</html>
